package pe.edu.lab16.asistentes;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import java.util.List;
@RestController @RequestMapping("/asistentes") public class AsistenteController{private final AsistenteService s;public AsistenteController(AsistenteService s){this.s=s;}@GetMapping public List<Asistente> listar(){return s.listar();}@GetMapping("/{id}") public Asistente obtener(@PathVariable Long id){return s.obtener(id);}@PostMapping public ResponseEntity<Asistente> crear(@Valid @RequestBody AsistenteRequest r){return ResponseEntity.status(201).body(s.crear(r));}@PutMapping("/{id}") public Asistente actualizar(@PathVariable Long id,@Valid @RequestBody AsistenteRequest r){return s.actualizar(id,r);}@DeleteMapping("/{id}") public ResponseEntity<Void> eliminar(@PathVariable Long id){s.eliminar(id);return ResponseEntity.noContent().build();}}
